window.RP_SESSION={"id":"S-259a89931e65","messages":[{"id":"RP-0166695","time":"2026-05-28T18:38:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-0166696","time":"2026-05-28T21:03:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"오늘의 저녁 식사는 흑빵과 오래된 치즈, 그리고 순무 스튜였다. 물론 말이 순무 스튜지, 식사 당번이 델타인이나 폰타니움이 아닌 카프리제였기에 테이블엔 썩 호화로운 메뉴가 나왔다.\n\n꽃잎과 치자 따위로 향을 낸 스튜에는 순무보다 시어링한 돼지고기가 더 많이 들어 있었고, 마무리로 날달걀과 양젖까지 곁들여진 채였다.\n\n스튜를 네 그릇째 비우고 등받이에 깊이 늘어졌다. 여전히 나무 수저를 쓰면 하루에 두어 개씩 부서뜨리기 일쑤였기에, 쇠로 만든 것을 써야했다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0166697","time":"2026-05-28T21:08:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션은 마력초 궐련에서 빼낸 가루를 파이프에 채우고 불을 붙여 입에 물었다. 그때까지도 수저를 쥐고 있던 의수는 굉장히 정교하게 남의 손을 이어붙인 듯 손에 아무런 감각이 없었다.\n\n당장 바느질도 할 수 있을 것처럼 움직이는 주제에 감각만큼은 없다니, 위화감이 넘친다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0166698","time":"2026-05-28T21:11:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"밤하늘을 유성이 가로질러가는 것보다도 짧은 시간. 찰나에 시원한 기운이 온몸을 쓸고 지나갔다. 그 상쾌하고 푸른 감각은 묵빛 의수로 향했다.\n\n션이 삼키기 전보다 마력이 줄어든 연기를 내뱉었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0166699","time":"2026-05-28T21:11:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9"]},{"id":"RP-0166700","time":"2026-05-28T21:11:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-0166701","time":"2026-05-28T21:14:00+09:00","room":"RP","name":"리엔","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"후루룩후루룩","characters":["P-a161473e74e0"]},{"id":"RP-0166702","time":"2026-05-28T21:14:00+09:00","room":"RP","name":"리엔","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"션옆에서 마음편하게 나무수저로 맛있게 스튜를먹고있던 리엔.","characters":["P-a161473e74e0"]},{"id":"RP-0166703","time":"2026-05-28T21:14:00+09:00","room":"RP","name":"리엔","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-a161473e74e0"]},{"id":"RP-0166704","time":"2026-05-28T21:15:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
